// THREADS/16 rows per CTA over the concatenated row space [Q rows | K rows]; 2*n_rows is a multiple of 96,
// so it is divisible by 16 and 32: no row mask.
template <int THREADS, bool LOAD_S>
__global__ void __launch_bounds__(THREADS, 2048 / THREADS)
qk_rms_kernel(const float* __restrict__ q, const float* __restrict__ k,
              const float* __restrict__ wq, const float* __restrict__ wk,
              float* __restrict__ qo, float* __restrict__ ko, int n_rows, float eps) {
    constexpr int ROWS = THREADS / 16;
    const int grow = blockIdx.x * ROWS + (threadIdx.x >> 4);   // < 2*n_rows < 2^31 (host-checked)
    const int c = (threadIdx.x & 15) * 8;
    const bool is_k = grow >= n_rows;
    const int row = is_k ? grow - n_rows : grow;
    const int head = row % H;
    const float* __restrict__ x = is_k ? k : q;
    const float* __restrict__ w = is_k ? wk : wq;
    float* __restrict__ y = is_k ? ko : qo;

    float xv[8], wv[8], yv[8];
    if (LOAD_S) {
        ld8_h(x + (size_t)row * D + c, xv, POL_EVICT_FIRST);
        ld8_nc(w + head * D + c, wv);
    } else {
        ld8(x + (size_t)row * D + c, xv);
        ld8(w + head * D + c, wv);
    }
    const uint64_t pol_out = pol_evict_last();

    float s = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) s = fmaf(xv[i], xv[i], s);
    s += __shfl_xor_sync(0xffffffffu, s, 8);
    s += __shfl_xor_sync(0xffffffffu, s, 4);
    s += __shfl_xor_sync(0xffffffffu, s, 2);
    s += __shfl_xor_sync(0xffffffffu, s, 1);
    const float inv = rsqrtf(s * (1.0f / (float)D) + eps);
#pragma unroll
    for (int i = 0; i < 8; ++i) yv[i] = (xv[i] * inv) * wv[i];
    st8_h(y + (size_t)row * D + c, yv, pol_out);
}
}  // namespace

// band: 0 = S (256 thr, EF loads + nc weights), 1 = M (256 thr, default loads), 2 = L (512 thr, default loads)
extern "C" cudaError_t qk_rms_launch(const float* q, const float* k, const float* wq, const float* wk,
                                      float* qo, float* ko, int n_rows, float eps, int band, cudaStream_t st) {
    const int total = 2 * n_rows;
    if (band == 2) {
        qk_rms_kernel<512, false><<<total / 32, 512, 0, st>>>(q, k, wq, wk, qo, ko, n_rows, eps);
    } else if (band == 1) {
        qk_rms_kernel<256, false><<<total / 16, 256, 0, st>>>(q, k, wq, wk, qo, ko, n_rows, eps);
    } else {
        qk_rms_kernel<256, true><<<total / 16, 256, 0, st>>>(q, k, wq, wk, qo, ko, n_rows, eps);
    }
    return cudaGetLastError();
}
